    desc: "「投资记账」页标题栏新增完整版风格切换样式的按钮（堆叠图层图标），点击展开导入与导出菜单：导出 Excel（有知有行格式）、导出 JSON、导入账本（Excel 或 JSON）。\n导出的 xlsx 与有知有行投资记账表完全兼容（账户名称、预期年化收益率、币种、四笔钱分类，以及每日总资产与转入转出记录），可来回导入导出；导入按账户名去重、避免重复账户；新增依赖 SheetJS(xlsx) 在服务端解析与生成。\n导入时按账户名称关键词用正则自动归入对应账本（如「富途」→ 美股（富途）、「长桥」→ 美股（长桥）、「ibkr/盈透」→ 美股（IBKR）、「港A」→ A股（港A）），账户名未命中时可按文件名兜底匹配（如「有知有行_华泰_xxx.xlsx」→ A股（华泰））；关键词库扩充至富途、长桥、IBKR、老虎、雪盈、微牛、嘉信、华泰、中信、招商、国泰君安、银河、广发、东方财富、雪球、且慢、蛋卷、天天基金、蚂蚁、币安、OKX、火币、港A 等；投资列表按账本分组并显示账户数与小计金额。",
