    desc: "现象：卡面库的搜索框与下拉一聚焦就出现一圈深蓝色描边，和全站的中性风格不搭。\n根因：globals.css 的「点击 / 激活 / 聚焦一律无轮廓、无光晕」只覆盖了 button / a / [role=button] / input[type=button|submit]，文本输入、文本域与下拉没有被覆盖，保留了浏览器默认的 focus ring。\n修复：把 input:not([type=checkbox]):not([type=radio])、textarea、select 的 :focus 与 :focus-visible 一并补进全局 outline: none 规则（复选框与单选框保留自己的焦点样式，避免误伤行情板等已有设计）；同时给卡面库的搜索框、下拉、金额 / 备注 / 标签输入补上全站同款的中性灰柔光焦点反馈。",
