    title: "卡面库筛选计数改为分面联动",
    desc: "现象：搜「招商」后列表只剩招商银行的卡，但「类型」胶囊仍写着 全部 436 / 借记卡 253 / 信用卡 172 / 预付卡 1 / 其他 10。\n根因：各维度的计数是拿「当前模式的全量集合」直接算的，没有参考搜索词与其他筛选。\n改为标准的分面统计：统计某个维度时把这个维度自己排除在外、其余条件全部生效 —— 搜「招商」时类型胶囊显示 全部 85 / 借记卡 60 / 信用卡 24 / 其他 1，卡组织下拉只剩 UnionPay 83 / MasterCard 1，银行下拉只剩招商银行。\n地区与银行的下拉选项列表本身也随条件收敛，不会出现「选了条件却列出一堆必然为 0 的选项」。",
